WITH ValidEmployees AS (SELECT *, CASE WHEN salary >= 156000 THEN 'High' WHEN salary >= 44000 THEN 'Medium' ELSE 'Low' END AS salary_band FROM employees WHERE dept_id IN (4, 8, 29, 33)), hire_month_summary AS (SELECT DATE_FORMAT(hire_date, 'yyyy-MM') AS hire_month, SUM(CASE WHEN job_title = 'Manager' THEN salary ELSE 0 END) AS manager_salary FROM ValidEmployees GROUP BY DATE_FORMAT(hire_date, 'yyyy-MM')) SELECT hire_month, manager_salary FROM hire_month_summary WHERE manager_salary > 22 ORDER BY hire_month DESC
